/// Fills the editor colors from the scheme; unmapped fields keep `e`'s value.
fn editor(mut e: EditorColors) -> EditorColors {
    e.background = px(0x2B2B2BFF); // TEXT.bg
    e.text = px(0xA9B7C6FF); // TEXT.fg
    e.caret = px(0xBBBBBBFF); // CARET_COLOR
    e.caret_row = px(0x323232FF); // CARET_ROW_COLOR
    e.line_number = px(0x606366FF); // LINE_NUMBERS_COLOR
    e.line_number_caret = px(0xA4A3A3FF); // LINE_NUMBER_ON_CARET_ROW_COLOR
    e.selection = px(0x214283FF); // SELECTION_BACKGROUND
    e.background_panel = px(0x46484AFF); // DOCUMENTATION_COLOR
    e.search_result = px(0x32593DFF); // TEXT_SEARCH_RESULT_ATTRIBUTES.bg
    e.rename_occurrence = px(0x344134FF); // IDENTIFIER_UNDER_CARET_ATTRIBUTES.bg
    e.matched_brace = px(0x3B514DFF); // MATCHED_BRACE_ATTRIBUTES.bg
    e.indent_guide = px(0x373737FF); // INDENT_GUIDE
    e.error_effect = px(0xBC3F3CFF); // ERRORS_ATTRIBUTES.effect
    e.warning_effect = px(0xBE9117FF); // WARNING_ATTRIBUTES.stripe
    e.weak_warning_effect = px(0xAEAE80FF); // INFO_ATTRIBUTES.effect
    e.breakpoint_line = px(0x3A2323FF); // BREAKPOINT_ATTRIBUTES.bg
    e.execution_line = px(0x2D6099FF); // EXECUTIONPOINT_ATTRIBUTES.bg
    e.inline_value = px(0x666D75FF); // DEBUGGER_INLINED_VALUES.fg
    e.error_stripe = px(0x9E2927FF); // ERRORS_ATTRIBUTES.stripe
    e.warning_stripe = px(0xBE9117FF); // WARNING_ATTRIBUTES.stripe
    e.string = px(0x6A8759FF); // DEFAULT_STRING.fg
    e.number = px(0x6897BBFF); // DEFAULT_NUMBER.fg
    e.keyword = px(0xCC7832FF); // DEFAULT_KEYWORD.fg
    e.constant = px(0x9876AAFF); // DEFAULT_CONSTANT.fg
    e.type_name = px(0x507874FF); // TYPE_PARAMETER_NAME_ATTRIBUTES.fg
    e.annotation = px(0xBBB529FF); // DEFAULT_METADATA.fg
    e.property = px(0x9876AAFF); // DEFAULT_INSTANCE_FIELD.fg
    e.punctuation = px(0xCC7832FF); // DEFAULT_COMMA.fg
    e.comment = px(0x808080FF); // DEFAULT_LINE_COMMENT.fg
    e.tag = px(0xE8BF6AFF); // XML_TAG_NAME.fg
    e.attribute = px(0xBABABAFF); // XML_ATTRIBUTE_NAME.fg
    e.variable = px(0xFFC66DFF); // DEFAULT_FUNCTION_DECLARATION.fg
    e.invalid = px(0xBC3F3CFF); // WRONG_REFERENCES_ATTRIBUTES.fg
    // Kept at the measured value: search_result_current.
    e
}
